**What this code covers**

- Helper to display MRO clearly
- class Z(X, Y): pass
- Base view — equivalent to Django's View
- Mixin: requires authenticated user
- CASE 1: Simple Single Inheritance
- MRO: C → B → A → object
- CASE 2: Multiple Inheritance (Diamond)
- MRO: Diamond → Left → Right → Base → object

**Defines:** `show_mro()`, `A`, `B`, `C`, `Base`, `Left`, `Right`, `Diamond`, `F`, `E`

### ✅ Example 1 — MRO Visualization & C3 Algorithm

```python name=example1_mro_visualization.py
# ══════════════════════════════════════════════════
#  UNDERSTANDING MRO STEP BY STEP
# ══════════════════════════════════════════════════

def show_mro(cls):
    """Helper to display MRO clearly"""
    mro = cls.__mro__
    print(f"\n{'='*50}")
    print(f"MRO for {cls.__name__}:")
    for i, c in enumerate(mro):
        arrow = "→" if i < len(mro)-1 else "✓"
        print(f"  {i+1}. {c.__name__} {arrow}")
    print(f"{'='*50}")

# ─── CASE 1: Simple Single Inheritance ───
class A:
    def method(self): print("A.method")

class B(A):
    def method(self): print("B.method")

class C(B):
    pass   # no override → uses B.method

# MRO: C → B → A → object
show_mro(C)
C().method()   # B.method (first one found going up MRO)

# ─── CASE 2: Multiple Inheritance (Diamond) ───
class Base:
    def speak(self):
        print(f"  Base.speak")

class Left(Base):
    def speak(self):
        print(f"  Left.speak")
        super().speak()   # next in MRO!

class Right(Base):
    def speak(self):
        print(f"  Right.speak")
        super().speak()   # next in MRO!

class Diamond(Left, Right):
    def speak(self):
        print(f"  Diamond.speak")
        super().speak()   # triggers chain!

# MRO: Diamond → Left → Right → Base → object
show_mro(Diamond)

print("\nDiamond().speak() — each class called ONCE:")
Diamond().speak()
# Diamond.speak
# Left.speak
# Right.speak
# Base.speak  ← called once (not twice!)

# ─── CASE 3: Complex Hierarchy ───
class F:
    def greet(self): print("  F")

class E(F):
    def greet(self): print("  E"); super().greet()

class D(F):
    def greet(self): print("  D"); super().greet()

class C2(D, F):
    def greet(self): print("  C2"); super().greet()

class B2(E, D):
    def greet(self): print("  B2"); super().greet()

class A2(B2, C2):
    def greet(self): print("  A2"); super().greet()

show_mro(A2)
print(f"\nA2().greet():")
A2().greet()

# ─── CASE 4: MRO determines which method is found ───
class Animal:
    def sound(self): return "..."
    def move(self):  return "moves generically"

class Pet(Animal):
    def sound(self): return "pet sound"

class Wild(Animal):
    def sound(self): return "wild sound"
    def hunt(self):  return "hunts"

class DomesticDog(Pet, Wild):
    pass   # no overrides — MRO decides everything!

# MRO: DomesticDog → Pet → Wild → Animal → object
show_mro(DomesticDog)

dog = DomesticDog()
print(f"\ndog.sound() = '{dog.sound()}'")  # 'pet sound' (Pet comes first!)
print(f"dog.hunt()  = '{dog.hunt()}'")    # 'hunts' (from Wild — Pet doesn't have it)
print(f"dog.move()  = '{dog.move()}'")    # 'moves generically' (from Animal)

# ─── CASE 5: Impossible MRO ───
class X: pass
class Y(X): pass

try:
    # This would create an inconsistent MRO!
    # C3 algorithm detects and raises TypeError
    exec("""
class Z(X, Y): pass
""")
except TypeError as e:
    print(f"\n❌ Impossible MRO: {e}")
    # X appears before Y in Z's parents,
    # but Y inherits from X (X must come AFTER Y!)
```

### ✅ Example 2 — `super()` and MRO Chain

```python name=example2_super_mro.py
# ══════════════════════════════════════════════════
#  SUPER() FOLLOWS THE MRO — not just the direct parent
# ══════════════════════════════════════════════════

# ─── The key insight: super() doesn't mean "my parent"
#     It means "the NEXT class in the MRO of the instance's class" ───

class LogMixin:
    def save(self):
        print("  [LOG] Before save")
        super().save()    # passes to next in MRO
        print("  [LOG] After save")

class ValidationMixin:
    def save(self):
        print("  [VALIDATE] Validating data...")
        super().save()    # passes to next in MRO
        print("  [VALIDATE] Validation done")

class CacheMixin:
    def save(self):
        print("  [CACHE] Clearing cache...")
        super().save()    # passes to next in MRO
        print("  [CACHE] Cache cleared")

class BaseModel:
    def save(self):
        print("  [DB] Actually saving to database!")   # the real work
        # No super().save() here — stops the chain

class UserModel(LogMixin, ValidationMixin, CacheMixin, BaseModel):
    def save(self):
        print("  [USER] UserModel.save() called")
        super().save()   # starts the chain

# MRO: UserModel → LogMixin → ValidationMixin → CacheMixin → BaseModel → object
print("MRO for UserModel:")
for c in UserModel.__mro__:
    print(f"  → {c.__name__}")

print("\nUserModel().save():")
UserModel().save()

# ─── super() with explicit class and instance ───
# super(MyClass, self) — explicit form useful in Python 2 and edge cases
class Animal:
    def __init__(self, name):
        self.name = name
        print(f"  Animal.__init__({name})")

class Pet(Animal):
    def __init__(self, name, owner):
        super(Pet, self).__init__(name)   # explicit super — same as super()
        self.owner = owner
        print(f"  Pet.__init__(owner={owner})")

class Dog(Pet):
    def __init__(self, name, owner, breed):
        super().__init__(name, owner)   # shorthand super()
        self.breed = breed
        print(f"  Dog.__init__(breed={breed})")

print("\n--- super() call chain through __init__ ---")
dog = Dog("Rex", "Alice", "Labrador")
print(f"Result: name={dog.name}, owner={dog.owner}, breed={dog.breed}")

# ─── super() in mixin context ───
class JsonMixin:
    def to_dict(self):
        # Gets the dict from the next class in MRO
        data = super().to_dict() if hasattr(super(), 'to_dict') else {}
        data['_type'] = self.__class__.__name__
        return data

class TimestampMixin:
    from datetime import datetime
    def to_dict(self):
        data = super().to_dict() if hasattr(super(), 'to_dict') else {}
        data['created_at'] = str(self.__class__.__name__)
        return data

class Product:
    def __init__(self, name, price):
        self.name  = name
        self.price = price

    def to_dict(self):
        return {"name": self.name, "price": self.price}

class FullProduct(JsonMixin, TimestampMixin, Product):
    def __init__(self, name, price, category):
        super().__init__(name, price)
        self.category = category

    def to_dict(self):
        data = super().to_dict()
        data['category'] = self.category
        return data

print("\n--- Mixin chain via super() ---")
print("MRO:", [c.__name__ for c in FullProduct.__mro__])
fp   = FullProduct("Laptop", 75000, "Electronics")
data = fp.to_dict()
print(f"Result: {data}")
```

### ✅ Example 3 — Practical MRO in Real Framework Design

```python name=example3_practical_mro.py
# ══════════════════════════════════════════════════
#  REAL-WORLD MRO — Django-style View CBV + Mixins
# ══════════════════════════════════════════════════

class View:
    """Base view — equivalent to Django's View"""

    def dispatch(self, request, *args, **kwargs):
        method_name = request.get('method', 'get').lower()
        handler     = getattr(self, method_name, self.http_method_not_allowed)
        return handler(request, *args, **kwargs)

    def http_method_not_allowed(self, request, *args, **kwargs):
        return {"status": 405, "error": "Method Not Allowed"}

    def get(self, request, *args, **kwargs):
        return {"status": 405, "error": "GET not implemented"}

    def post(self, request, *args, **kwargs):
        return {"status": 405, "error": "POST not implemented"}

class LoginRequiredMixin:
    """Mixin: requires authenticated user"""

    def dispatch(self, request, *args, **kwargs):
        if not request.get('user', {}).get('authenticated', False):
            return {"status": 401, "error": "Login required", "redirect": "/login/"}
        return super().dispatch(request, *args, **kwargs)  # chain!

class PermissionRequiredMixin:
    """Mixin: requires specific permission"""

    required_permission = None

    def dispatch(self, request, *args, **kwargs):
        user  = request.get('user', {})
        perms = user.get('permissions', [])
        if self.required_permission and self.required_permission not in perms:
            return {
                "status": 403,
                "error" : f"Permission '{self.required_permission}' required"
            }
        return super().dispatch(request, *args, **kwargs)  # chain!

class LoggingMixin:
    """Mixin: logs all requests"""

    def dispatch(self, request, *args, **kwargs):
        user   = request.get('user', {}).get('username', 'anonymous')
        method = request.get('method', 'GET').upper()
        path   = request.get('path', '/')
        print(f"  📋 [{method}] {path} by {user}")
        result = super().dispatch(request, *args, **kwargs)  # chain!
        print(f"  📋 Response status: {result.get('status', 200)}")
        return result

class RateLimitMixin:
    """Mixin: rate limiting"""
    _rate_counters = {}
    max_requests   = 100

    def dispatch(self, request, *args, **kwargs):
        user = request.get('user', {}).get('username', 'anonymous')
        self._rate_counters[user] = self._rate_counters.get(user, 0) + 1
        if self._rate_counters[user] > self.max_requests:
            return {"status": 429, "error": "Too Many Requests"}
        return super().dispatch(request, *args, **kwargs)  # chain!

# ─── Concrete Views ───
class ReportListView(LoggingMixin, LoginRequiredMixin, View):
    """Basic authenticated view with logging"""

    def get(self, request, *args, **kwargs):
        return {
            "status"  : 200,
            "reports" : ["Q1-2026", "Q2-2026", "Q3-2026"]
        }

class AdminReportView(LoggingMixin, LoginRequiredMixin,
                      PermissionRequiredMixin, RateLimitMixin, View):
    """Full-stack view with all mixins"""

    required_permission = "admin_reports"
    max_requests        = 10

    def get(self, request, *args, **kwargs):
        return {
            "status" : 200,
            "data"   : "Sensitive admin report data"
        }

    def post(self, request, *args, **kwargs):
        return {"status": 201, "message": "Report created"}

# ─── Testing ───
def show_view_mro(view_cls):
    print(f"\nMRO for {view_cls.__name__}:")
    for c in view_cls.__mro__:
        if c.__name__ != 'object':
            print(f"  → {c.__name__}")

show_view_mro(ReportListView)
show_view_mro(AdminReportView)

print("\n=== ReportListView ===")
view = ReportListView()

# Anonymous request — login required
print("\n[Anonymous GET]:")
anon_req = {"method": "get", "path": "/reports/", "user": {}}
print(view.dispatch(anon_req))

# Authenticated request
print("\n[Authenticated GET]:")
auth_req = {
    "method": "get",
    "path"  : "/reports/",
    "user"  : {"username": "alice", "authenticated": True}
}
print(view.dispatch(auth_req))

print("\n=== AdminReportView ===")
admin_view = AdminReportView()

# Has login but not admin permission
print("\n[User without permission]:")
user_req = {
    "method": "get", "path": "/admin/reports/",
    "user"  : {"username": "bob", "authenticated": True, "permissions": ["view"]}
}
print(admin_view.dispatch(user_req))

# Full admin
print("\n[Admin user]:")
admin_req = {
    "method": "get", "path": "/admin/reports/",
    "user"  : {"username": "carol", "authenticated": True,
               "permissions": ["view", "admin_reports"]}
}
print(admin_view.dispatch(admin_req))
```

### ✅ Example 4 — MRO with `__init__` and Cooperative Multiple Inheritance

```python name=example4_cooperative_init.py
# ══════════════════════════════════════════════════
#  COOPERATIVE MULTIPLE INHERITANCE
#  ALL __init__ methods called via super() chain
# ══════════════════════════════════════════════════

class TimestampMixin:
    def __init__(self, *args, **kwargs):
        from datetime import datetime
        super().__init__(*args, **kwargs)   # pass remaining args up!
        self.created_at = datetime.now()
        self.updated_at = datetime.now()
        print(f"  ✅ TimestampMixin: timestamps set")

    def touch(self):
        from datetime import datetime
        self.updated_at = datetime.now()

class SoftDeleteMixin:
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.is_deleted   = False
        self.deleted_at   = None
        print(f"  ✅ SoftDeleteMixin: soft delete initialized")

    def soft_delete(self):
        from datetime import datetime
        self.is_deleted = True
        self.deleted_at = datetime.now()
        print(f"  🗑️  Soft deleted at {self.deleted_at}")

    def restore(self):
        self.is_deleted = False
        self.deleted_at = None
        print(f"  ♻️  Restored")

class AuditMixin:
    def __init__(self, created_by=None, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.created_by = created_by
        self.change_log  = []
        print(f"  ✅ AuditMixin: audit trail initialized (by: {created_by})")

    def log_change(self, field, old_val, new_val):
        from datetime import datetime
        self.change_log.append({
            "field"  : field,
            "old"    : old_val,
            "new"    : new_val,
            "time"   : datetime.now().isoformat()
        })

class BaseModel:
    def __init__(self, model_id, *args, **kwargs):
        super().__init__(*args, **kwargs)   # important even for base!
        self.id = model_id
        print(f"  ✅ BaseModel: id={model_id} set")

    def save(self):
        print(f"  💾 Saving {self.__class__.__name__} id={self.id}")

# ─── Full model using all mixins ───
class UserRecord(TimestampMixin, SoftDeleteMixin, AuditMixin, BaseModel):
    def __init__(self, user_id, username, email, created_by=None):
        print(f"\n--- Creating UserRecord ---")
        # super() triggers the MRO chain through ALL __init__ methods!
        super().__init__(
            model_id   = user_id,
            created_by = created_by
        )
        self.username = username
        self.email    = email
        print(f"  ✅ UserRecord fields set: {username}, {email}")

    def update_email(self, new_email):
        old = self.email
        self.email = new_email
        self.log_change("email", old, new_email)
        self.touch()

print("MRO for UserRecord:")
for c in UserRecord.__mro__:
    print(f"  → {c.__name__}")

user = UserRecord(1, "alice_dev", "alice@test.com", created_by="system")

print(f"\n--- User Created ---")
print(f"ID         : {user.id}")
print(f"Username   : {user.username}")
print(f"Email      : {user.email}")
print(f"Created at : {user.created_at}")
print(f"Created by : {user.created_by}")
print(f"Is deleted : {user.is_deleted}")

print(f"\n--- Update email ---")
user.update_email("alice_new@test.com")
print(f"Change log : {user.change_log}")

print(f"\n--- Soft delete ---")
user.soft_delete()
print(f"Is deleted : {user.is_deleted}")
print(f"Deleted at : {user.deleted_at}")

print(f"\n--- Restore ---")
user.restore()
user.save()
```

### ✅ Example 5 — MRO Edge Cases & Debugging

```python name=example5_mro_edge_cases.py
# ══════════════════════════════════════════════════
#  MRO EDGE CASES, DEBUGGING, AND BEST PRACTICES
# ══════════════════════════════════════════════════

# ─── Edge Case 1: Mixin placement matters! ───
class FileLogger:
    def log(self, msg):
        print(f"  [FILE] {msg}")

class ConsoleLogger:
    def log(self, msg):
        print(f"  [CONSOLE] {msg}")

class NullLogger:
    def log(self, msg):
        pass   # silently ignore

# Different mixin placement = different MRO = different log() called!
class ServiceA(FileLogger, ConsoleLogger):
    """FileLogger comes first → its log() wins"""
    pass

class ServiceB(ConsoleLogger, FileLogger):
    """ConsoleLogger comes first → its log() wins"""
    pass

class ServiceC(NullLogger, FileLogger, ConsoleLogger):
    """NullLogger first → no output"""
    pass

print("=== Mixin Order Determines Behavior ===")
ServiceA().log("Hello")   # [FILE] Hello
Service
```

```python name=example5_mro_edge_cases.py
# ══════════════════════════════════════════════════
#  MRO EDGE CASES, DEBUGGING, AND BEST PRACTICES
# ══════════════════════════════════════════════════

# ─── Edge Case 1: Mixin placement matters! ───
class FileLogger:
    def log(self, msg):
        print(f"  [FILE] {msg}")

class ConsoleLogger:
    def log(self, msg):
        print(f"  [CONSOLE] {msg}")

class NullLogger:
    def log(self, msg):
        pass   # silently ignore

class ServiceA(FileLogger, ConsoleLogger):
    """FileLogger comes first → its log() wins"""
    pass

class ServiceB(ConsoleLogger, FileLogger):
    """ConsoleLogger comes first → its log() wins"""
    pass

class ServiceC(NullLogger, FileLogger, ConsoleLogger):
    """NullLogger first → no output at all"""
    pass

print("=== Mixin Order Determines Behavior ===")
ServiceA().log("Hello")    # [FILE] Hello
ServiceB().log("Hello")    # [CONSOLE] Hello
ServiceC().log("Hello")    # (silence — NullLogger wins)

print(f"\nServiceA MRO: {[c.__name__ for c in ServiceA.__mro__]}")
print(f"ServiceB MRO: {[c.__name__ for c in ServiceB.__mro__]}")
print(f"ServiceC MRO: {[c.__name__ for c in ServiceC.__mro__]}")

# ─── Edge Case 2: super() without override can skip levels ───
class A:
    def process(self):
        print("  A.process")

class B(A):
    def process(self):
        print("  B.process")
        super().process()

class C(A):
    # NOTE: C does NOT override process()
    pass

class D(B, C):
    pass   # no override either

# MRO: D → B → C → A
# When B calls super().process(), it goes to C, but C has no process()
# so it goes to A.process() — this is CORRECT and expected!
print("\n=== super() skips classes without the method ===")
print(f"D MRO: {[c.__name__ for c in D.__mro__]}")
D().process()   # B.process → A.process (C skipped — no override)

# ─── Edge Case 3: Breaking the chain (not calling super()) ───
class LogMixinBroken:
    def save(self):
        print("  [LOG] saving...")
        # ❌ FORGOT super().save()! Chain BROKEN here!

class ValidateMixin:
    def save(self):
        print("  [VALIDATE] validating...")
        super().save()

class DBBase:
    def save(self):
        print("  [DB] writing to database!")

class BrokenModel(LogMixinBroken, ValidateMixin, DBBase):
    def save(self):
        print("  [MODEL] BrokenModel.save()")
        super().save()

class WorkingModel(ValidateMixin, LogMixinBroken, DBBase):
    def save(self):
        print("  [MODEL] WorkingModel.save()")
        super().save()

print("\n=== Broken chain (LogMixin doesn't call super) ===")
print("BrokenModel MRO:", [c.__name__ for c in BrokenModel.__mro__])
BrokenModel().save()
# ValidateMixin saves → LogMixinBroken saves → STOPS (no super)
# DBBase.save() NEVER called!

print("\nWorkingModel MRO:", [c.__name__ for c in WorkingModel.__mro__])
WorkingModel().save()
# ValidateMixin → LogMixinBroken → STOPS again!
print("⚠️  DB never written because LogMixinBroken breaks the chain!")

# ─── Edge Case 4: MRO debugging utility ───
def mro_report(cls):
    """Comprehensive MRO analysis report"""
    print(f"\n{'═'*55}")
    print(f"  MRO ANALYSIS: {cls.__name__}")
    print(f"{'═'*55}")
    print(f"  Full MRO Chain:")
    for i, c in enumerate(cls.__mro__):
        indent = "  " * min(i, 5)
        print(f"    {i+1:2d}. {indent}{c.__name__}")

    print(f"\n  Method Resolution for common methods:")
    for method_name in ['__init__', 'save', 'process', 'log', 'validate']:
        for c in cls.__mro__:
            if method_name in c.__dict__:
                print(f"    {method_name:<15} → {c.__name__}")
                break

    print(f"\n  All unique methods available:")
    all_methods = set()
    for c in cls.__mro__:
        for name in c.__dict__:
            if not name.startswith('__') and callable(c.__dict__[name]):
                all_methods.add(name)
    for m in sorted(all_methods):
        for c in cls.__mro__:
            if m in c.__dict__:
                print(f"    {m:<20} → defined in {c.__name__}")
                break
    print(f"{'═'*55}")

# ─── Edge Case 5: Proper cooperative __init__ pattern ───
class MixinA:
    def __init__(self, **kwargs):
        print(f"  MixinA.__init__ | remaining kwargs: {kwargs}")
        super().__init__(**kwargs)   # pass remaining kwargs up!

class MixinB:
    def __init__(self, **kwargs):
        print(f"  MixinB.__init__ | remaining kwargs: {kwargs}")
        super().__init__(**kwargs)

class Base:
    def __init__(self, **kwargs):
        print(f"  Base.__init__ | remaining kwargs: {kwargs}")
        # Don't pass kwargs further — Base is the end of the chain

class MyClass(MixinA, MixinB, Base):
    def __init__(self, x, y, **kwargs):
        print(f"  MyClass.__init__(x={x}, y={y})")
        super().__init__(**kwargs)   # pass unknown kwargs up the chain
        self.x = x
        self.y = y

print("\n=== Cooperative __init__ with **kwargs ===")
print("MRO:", [c.__name__ for c in MyClass.__mro__])
obj = MyClass(x=1, y=2)

# ─── Best Practice Summary ───
print("\n" + "═"*55)
print("  MRO BEST PRACTICES CHECKLIST")
print("═"*55)
practices = [
    "✅ Always call super().__init__(**kwargs) in mixins",
    "✅ Use **kwargs to pass unrecognized args up the chain",
    "✅ Place most-specific mixins leftmost in class definition",
    "✅ Check __mro__ when behavior is unexpected",
    "✅ Mixins should ALWAYS call super() to preserve chain",
    "✅ Use @functools.wraps when wrapping methods in mixins",
    "❌ Never break the super() chain in mixins",
    "❌ Don't assume super() calls YOUR direct parent",
    "❌ Avoid more than 3-4 levels of mixin depth",
]
for p in practices:
    print(f"  {p}")
```
